import io
import tokenize
from pathlib import Path

import pytest

BACKEND = Path(__file__).resolve().parents[1]
CODE = ("src", "tests", "migrations")
DIRECTIVES = (
    "noqa",
    "type:",
    "pragma",
    "fmt:",
    "isort:",
    "commands auto generated by Alembic",
    "end Alembic commands",
)


def python_files() -> list[Path]:
    return sorted(
        path
        for directory in CODE
        for path in (BACKEND / directory).rglob("*.py")
        if ".venv" not in path.parts and "__pycache__" not in path.parts
    )


@pytest.mark.parametrize(
    "path", python_files(), ids=lambda p: str(p.relative_to(BACKEND))
)
def test_python_code_has_no_comments(path: Path) -> None:
    found = [
        f"line {token.start[0]}: {token.string}"
        for token in tokenize.generate_tokens(io.StringIO(path.read_text()).readline)
        if token.type == tokenize.COMMENT
        and not token.string.startswith("#!")
        and not token.string.lstrip("# ").startswith(DIRECTIVES)
    ]

    assert found == []
